#!/usr/bin/env python3
# d314_docs_parche.py — DAY314, cierre del día: prompt_day315.md (nuevo) y sección DAY312–314 al final de BACKLOG.md.
# Parcheador de UN SOLO USO (no se commitea). Parte de feat/etcd-mtls-vault en 0ddfe530 (4b.4).
#   python3 scripts/d314_docs_parche.py --check    dice, fichero a fichero, si está listo, ya aplicado o distinto
#   python3 scripts/d314_docs_parche.py --apply    escribe los 2 ficheros SOLO si todos están listos
# Se ejecuta en la raíz del repo (Mac). Valida TODO antes de escribir: sha256 de partida de cada fichero (o que no exista,
# si es nuevo) y sha256 final tras escribir. Un fichero que no está ni en el origen ni en el final = rechazo, sin
# escribir nada. Escritura atómica (temporal + rename), conserva los permisos de los ficheros que ya existían.
import base64, hashlib, json, os, sys, tempfile, zlib

CARGA = json.loads(r"""[
{
"ruta": "docs/BACKLOG.md",
"sha_origen": "0ea73cde49527b2992eb5d5d5eba4f47265574e3ae86e21e66e9a8bf9fe45d40",
"sha_final": "903d7918c21e24a56829a69bfb31456135b5bc1aeed38d1c0942e1b6b350deb5",
"datos": ""
},
{
"ruta": "docs/ml-heads/prompt_day315.md",
"sha_origen": null,
"sha_final": "651c2fbd0f2773d5c01102373c416a86029d44c057be21ee13363104b30222ad",
"datos": ""
}
]""")


def sha(ruta):
    try:
        with open(ruta, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()
    except FileNotFoundError:
        return None


def estado(e):
    actual = sha(e["ruta"])
    if actual == e["sha_final"]:
        return "ya aplicado"
    if actual == e["sha_origen"]:
        return "listo" if actual else "listo (nuevo)"
    return "DISTINTO (sha256 %s)" % (actual[:16] if actual else "no existe")


def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("--check", "--apply"):
        print("uso: python3 scripts/d314_docs_parche.py --check | --apply")
        return 2
    if not (os.path.isfile("Vagrantfile") and os.path.isdir("etcd-server") and os.path.isdir(".git")):
        print("[D314-PARCHE] FALLA: no estoy en la raíz del repo (Vagrantfile, etcd-server/, .git)")
        return 1
    est = [(e, estado(e)) for e in CARGA]
    for e, s in est:
        print("[D314-PARCHE] %-58s %s" % (e["ruta"], s))
    listos = sum(1 for _, s in est if s.startswith("listo"))
    hechos = sum(1 for _, s in est if s == "ya aplicado")
    malos = [e["ruta"] for e, s in est if s.startswith("DISTINTO")]
    n = len(CARGA)
    if hechos == n:
        print("[D314-PARCHE] ya aplicado (%d/%d)" % (n, n))
        return 0
    if malos or listos != n:
        print("[D314-PARCHE] FALLA: %d listos, %d ya aplicados, %d distintos de lo esperado: NO se escribe nada"
              % (listos, hechos, len(malos)))
        return 1
    print("[D314-PARCHE] %d listos" % n)
    if sys.argv[1] == "--check":
        return 0
    for e in CARGA:
        datos = zlib.decompress(base64.b64decode(e["datos"]))
        if hashlib.sha256(datos).hexdigest() != e["sha_final"]:
            print("[D314-PARCHE] FALLA: carga corrupta para %s: no se escribe nada" % e["ruta"])
            return 1
    for e in CARGA:
        datos = zlib.decompress(base64.b64decode(e["datos"]))
        ruta = e["ruta"]
        d = os.path.dirname(ruta) or "."
        os.makedirs(d, exist_ok=True)
        modo = os.stat(ruta).st_mode & 0o7777 if os.path.exists(ruta) else 0o644
        fd, tmp = tempfile.mkstemp(dir=d, prefix=".d314.")
        with os.fdopen(fd, "wb") as f:
            f.write(datos)
        os.chmod(tmp, modo)
        os.replace(tmp, ruta)
    mal = [e["ruta"] for e in CARGA if sha(e["ruta"]) != e["sha_final"]]
    if mal:
        print("[D314-PARCHE] FALLA: tras escribir, sha256 distinto en: %s" % ", ".join(mal))
        return 1
    print("[D314-PARCHE] aplicado (%d/%d); comprobar con --check" % (n, n))
    return 0


if __name__ == "__main__":
    sys.exit(main())
